problem:
Problem description
- There is a finite set of products $$\mathcal P$$, a finite set of process stages $$\mathcal Q=\{\mathsf A,\mathsf B\}$$, and a planning horizon $$\mathcal T$$ over which the production plan is evaluated.
- Process stage $$\mathsf A$$ can be executed on a set of machines $$\mathcal M_{\mathsf A}$$, and process stage $$\mathsf B$$ can be executed on a set of machines $$\mathcal M_{\mathsf B}$$.
- Each product $$p\in\mathcal P$$ must pass through both process stages in the required order before it becomes a finished item.
- For each product $$p$$ and process stage $$q$$, only a subset of machines is eligible; these eligibility sets are denoted by $$\mathcal E_{p}^{q}$$.
- Each eligible product-machine combination has a unit processing-time parameter, denoted by $$\tau_{p,m}^{q}$$, which consumes machine-hours on the chosen machine.
- Each machine $$m$$ has an available effective-hour capacity $$H_m$$ over the planning horizon.
- Each machine $$m$$ also has an operating-cost parameter $$F_m$$ associated with full-capacity operation.
- Each product $$p$$ has a raw-material cost parameter $$c_p^{\mathrm{raw}}$$ per unit and a unit selling price parameter $$\pi_p$$ per unit.
- If a generalized instance includes market limits, product demand is denoted by $$d_p$$; this instance does not impose an explicit demand cap.
- The optimization goal is to choose product quantities and machine assignments so that total profit over $$\mathcal T$$ is maximized.
- The business rules require that machine assignments respect eligibility, machine-hours cannot exceed available capacity, and the quantity completed through process $$\mathsf A$$ for each product must match the quantity that proceeds to process $$\mathsf B$$.

- A solution is represented by:
  - $$x_p$$: the total quantity of product $$p\in\mathcal P$$ produced and sold.
  - $$x_{p,m}^{\mathsf A}$$: the quantity of product $$p$$ routed to machine $$m\in\mathcal M_{\mathsf A}$$ for process stage $$\mathsf A$$.
  - $$x_{p,m}^{\mathsf B}$$: the quantity of product $$p$$ routed to machine $$m\in\mathcal M_{\mathsf B}$$ for process stage $$\mathsf B$$.
  - $$u_m$$: the total effective machine-hours used on machine $$m$$.
  - $$\Pi$$: the total profit achieved by the production plan.

Input Format
{
  "sets": {
    "products": {
      "symbol": "$$\\mathcal P$$",
      "description": "Finite set of product types indexed by $$p$$."
    },
    "processes": {
      "symbol": "$$\\mathcal Q=\\{\\mathsf A,\\mathsf B\\}$$",
      "description": "Required process stages."
    },
    "machines_A": {
      "symbol": "$$\\mathcal M_{\\mathsf A}$$",
      "description": "Machines eligible for process stage $$\\mathsf A$$."
    },
    "machines_B": {
      "symbol": "$$\\mathcal M_{\\mathsf B}$$",
      "description": "Machines eligible for process stage $$\\mathsf B$$."
    }
  },
  "parameters": {
    "raw_material_cost": {
      "symbol": "$$c_p^{\\mathrm{raw}}$$",
      "shape": "$$|\\mathcal P|$$",
      "description": "Raw-material cost per unit of product $$p$$."
    },
    "sale_price": {
      "symbol": "$$\\pi_p$$",
      "shape": "$$|\\mathcal P|$$",
      "description": "Unit selling price of product $$p$$."
    },
    "processing_time_A": {
      "symbol": "$$\\tau_{p,m}^{\\mathsf A}$$",
      "shape": "$$|\\mathcal P|\\times|\\mathcal M_{\\mathsf A}|$$",
      "description": "Unit processing time of product $$p$$ on machine $$m\\in\\mathcal M_{\\mathsf A}$$ for process $$\\mathsf A$$."
    },
    "processing_time_B": {
      "symbol": "$$\\tau_{p,m}^{\\mathsf B}$$",
      "shape": "$$|\\mathcal P|\\times|\\mathcal M_{\\mathsf B}|$$",
      "description": "Unit processing time of product $$p$$ on machine $$m\\in\\mathcal M_{\\mathsf B}$$ for process $$\\mathsf B$$."
    },
    "capacity_hours": {
      "symbol": "$$H_m$$",
      "shape": "$$|\\mathcal M_{\\mathsf A}|+|\\mathcal M_{\\mathsf B}|$$",
      "description": "Available effective machine-hours of machine $$m$$ over the planning horizon $$\\mathcal T$$."
    },
    "full_capacity_operating_cost": {
      "symbol": "$$F_m$$",
      "shape": "$$|\\mathcal M_{\\mathsf A}|+|\\mathcal M_{\\mathsf B}|$$",
      "description": "Operating-cost parameter associated with using machine $$m$$ at full capacity."
    },
    "eligibility": {
      "symbol": "$$\\mathcal E_p^{q}$$",
      "shape": "$$\\mathcal P\\times\\mathcal Q$$",
      "description": "Allowed machine set for product $$p$$ at process stage $$q$$."
    },
    "demand_optional": {
      "symbol": "$$d_p$$",
      "shape": "$$|\\mathcal P|$$",
      "description": "Optional demand or sales-limit parameter for product $$p$$, if included in a generalized instance."
    }
  },
  "decision_variables": {
    "production_quantity": {
      "symbol": "$$x_p$$",
      "shape": "$$|\\mathcal P|$$",
      "description": "Total quantity of product $$p$$ produced."
    },
    "routing_A": {
      "symbol": "$$x_{p,m}^{\\mathsf A}$$",
      "shape": "$$|\\mathcal P|\\times|\\mathcal M_{\\mathsf A}|$$",
      "description": "Quantity of product $$p$$ assigned to machine $$m$$ for process stage $$\\mathsf A$$."
    },
    "routing_B": {
      "symbol": "$$x_{p,m}^{\\mathsf B}$$",
      "shape": "$$|\\mathcal P|\\times|\\mathcal M_{\\mathsf B}|$$",
      "description": "Quantity of product $$p$$ assigned to machine $$m$$ for process stage $$\\mathsf B$$."
    },
    "machine_usage": {
      "symbol": "$$u_m$$",
      "shape": "$$|\\mathcal M_{\\mathsf A}|+|\\mathcal M_{\\mathsf B}|$$",
      "description": "Total effective machine-hours used on machine $$m$$."
    }
  }
}

Output Format
{
  "solution": {
    "production_quantity": {
      "symbol": "$$x_p$$",
      "shape": "$$|\\mathcal P|$$",
      "description": "Produced quantity for each product $$p$$."
    },
    "routing_A": {
      "symbol": "$$x_{p,m}^{\\mathsf A}$$",
      "shape": "$$|\\mathcal P|\\times|\\mathcal M_{\\mathsf A}|$$",
      "description": "Allocated quantity on each machine $$m\\in\\mathcal M_{\\mathsf A}$$ for process stage $$\\mathsf A$$."
    },
    "routing_B": {
      "symbol": "$$x_{p,m}^{\\mathsf B}$$",
      "shape": "$$|\\mathcal P|\\times|\\mathcal M_{\\mathsf B}|$$",
      "description": "Allocated quantity on each machine $$m\\in\\mathcal M_{\\mathsf B}$$ for process stage $$\\mathsf B$$."
    },
    "machine_usage": {
      "symbol": "$$u_m$$",
      "shape": "$$|\\mathcal M_{\\mathsf A}|+|\\mathcal M_{\\mathsf B}|$$",
      "description": "Effective machine-hours consumed by each machine."
    },
    "total_profit": {
      "symbol": "$$\\Pi$$",
      "shape": "$$1$$",
      "description": "Maximum total profit achieved by the plan."
    }
  }
}

